INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'esES', 'Consigue 5 motas de investigación del Omnium para usarlas en el folio del Omnium.', 'Estudios del folio del Omnium', 'Adorno de recompensa: simulacro del Omnium del Caminante del Sol', 68974),
(62903, 'esES', 'Disipa 5 tormentas en Val.', 'Clima extraño: Val', 'Mascota de recompensa: desbloquea la compra de Keith Palito de Pescado', 68974),
(63343, 'esES', 'Marca un tanto con la pelota de entrenamiento pateable en Lunargenta mientras llevas un tabardo de participación.', '¡Gol!', 'Adorno de recompensa: orbe de Azeroth preciado, orgullo de la Horda enmarcado y orgullo de la Alianza enmarcado', 68974),
(61336, 'esES', 'Honra las llamas de Midnight.', 'Celador de las llamas de Midnight', '', 68974),
(61335, 'esES', 'Honra las llamas de Midnight.', 'Vigilante de las Llamas de Midnight', '', 68974),
(61936, 'esES', 'Derrota a la Vanguardia Cegada por la Luz mientras toda tu banda tiene Aura máxima en la Aguja del Vacío en dificultad normal o superior.', 'Cosecha de aura', '', 68974),
(61911, 'esES', 'Derrota a Vaelgor y Ezzorak después de que todos los jugadores rompan cada atadura de la Zona de la nada en 3 s en la Aguja del Vacío en dificultad normal o superior.', 'Preparados, listos, ¡zas!', '', 68974),
(61514, 'esES', 'Derrota al rey caído Salhadaar después de que todos se arrodillen ante él antes de que comience la batalla en la Aguja del Vacío en dificultad normal o superior.', 'Traición, pues', '', 68974),
(61381, 'esES', 'Derrota a Belo\'ren, Hijo de Al\'ar después de imbuir el huevo de La Fuente del Sol con magia de la Luz y del Vacío en la Marcha a Quel\'Danas en dificultad normal o superior', '¿Qué fue primero?', '', 68974),
(61346, 'esES', 'Derrota a la corona del cosmos tras matar a una monstruosidad carnosa y devolver toda su carne a la Nada en la Aguja del Vacío en dificultad normal o superior.', 'Volveremos a verla, sin duda', '', 68974),
(61611, 'esES', 'Derrota a L\'ura en la Marcha a Quel\'Danas en dificultad mítica en un grupo de hermandad.', 'Mítica: Hermandad contra L\'ura', '', 68974),
(61380, 'esES', 'Completa los logros de banda listados a continuación.', 'Gloria del asaltante de Midnight', 'Montura: lacerante tenebroso', 68974),
(62874, 'esES', 'Completa los siguientes logros:', 'Un viaje a través de las estrellas', 'Recompensa: desbloquea la compra del ensamblaje nulo Forjabisal', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'esES', 'Folio del Omnium - Nueva información', 'Los Magistri disponen de información adicional que puede permitirte potenciar más runas en el folio del Omnium.', 'Aceptar misión', 'Otorga una mota de investigación del Omnium para potenciar otra runa en tu folio del Omnium.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'esES', 'Cubil de Predaxas', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'esES', 'MODO DE RELAJACIÓN: ACTIVADO.\nNIVEL DE RELAJACIÓN: MÁXIMO.\nTEMPERATURA INTERNA: BAJA.', '|cFFFFD200Promoción|r |n', 68974),
(4617, 'esES', 'DIRECTIVA PRINCIPAL: REALIZAR ACTOS HEROICOS.\nACTOS HEROICOS PREFERIDOS: EMOCIONANTES.\nDIRECTIVA SECUNDARIA: SER UN HÉROE.\nHÉROE PREFERIDO: GRANDE.', '|cFFFFD200Promoción|r |n', 68974),
(4949, 'esES', 'Un vestigio del intento de Fyrakk por corromper Amirdrassil.', '|cFFFFD200Vendedor: |rXydan|n|cFFFFD200Zona: |rValdrakken|n|cFFFFD200Coste: |r2200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'esES', 'A diferencia de los otros abisarios de la Tormenta del Vacío, Silento prefiere la paz y la tranquilidad del silencio. Aunque eso implique callar a los más charlatanes de su especie.', '|cFFFFD200Logros:|r Éxito en los enfrentamientos: Val y Éxito en los enfrentamientos: Naigtal |n|cFFFFD200Vendedor: |rKifaan|n|cFFFFD200Zonas: |rVal o Naigtal|n|cFFFFD200Coste: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'esES', 'Esta pequeña, decidida a estar a la altura de sus antepasados, está lista para armar jaleo. Ha decidido empezar por arañitas e ir subiendo el nivel poco a poco.', '|cFFFFD200Logro:|r Matanza en ultradón|n|cFFFFD200Vendedor: |rKifaan|n|cFFFFD200Zonas: |rVal o Naigtal|n|cFFFFD200Coste: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'esES', 'El pescado congelado es el manjar predilecto de Keith. Si tienes un poco, acabas de hacer un amigo.', '|cFFFFD200Logro:|r Clima extraño: Val|n|cFFFFD200Vendedor: |rKifaan|n|cFFFFD200Zona: |rNaigtal o Val|n|cFFFFD200Coste: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'esES', 'El comandante Tala\'saan echa a un lado su capa velada por la Luz y da un paso al frente.', '', 68974),
(314421, 'esES', '¡ARGH!', '', 68974),
(314420, 'esES', '¡CUIDADO, SOBRINO!', '', 68974),
(314419, 'esES', '¡NI A LOH HASH\'EY!', '', 68974),
(314418, 'esES', 'Con ehte poder, no necesitamoh a loh loa.', '', 68974),
(314417, 'esES', '¡No!', '', 68974),
(314416, 'esES', '¡Suéltala!', '', 68974),
(314415, 'esES', '¡Eh magia ohcura!', '', 68974),
(314414, 'esES', '¡Zul\'jan!', '', 68974),
(314413, 'esES', '<gruñido>', '', 68974),
(314412, 'esES', 'Debe de ser... la llave pa...', '', 68974),
(314411, 'esES', '¡Aquí ehtá!', '', 68974),
(314410, 'esES', '¡Ah!', '', 68974),
(314408, 'esES', 'te aseguro... que lo entenderá.', '', 68974),
(314407, 'esES', 'Y cuando te hayah hecho con el poder de Ula\'tek', '', 68974),
(314406, 'esES', 'Coge la llave, Zul\'jan.', '', 68974),
(314405, 'esES', 'Cuando vea a nuehtro tío...', '', 68974),
(314404, 'esES', 'Ehtá totalmente bajo la influencia de loh loa...', '', 68974),
(314403, 'esES', '¿Y mi hermana?', '', 68974),
(314402, 'esES', 'Terminemoh lo que empezamoh tu abuelo y yo.', '', 68974),
(314401, 'esES', 'sin las promesah vacíah de loh loa.', '', 68974),
(314400, 'esES', 'Aseguremoh el futuro de loh Amani', '', 68974),
(314399, 'esES', 'y necesito tu ayuda, Zul\'jan.', '', 68974),
(314398, 'esES', 'Malacrah', '', 68974),
(314397, 'esES', 'Sí...', '', 68974),
(314396, 'esES', 'Entonceh, debeh de ser...', '', 68974),
(314395, 'esES', '¿Conocihte a mi abuelo?', '', 68974),
(314394, 'esES', 'Zul\'jin y yo intentamoh cambiarlo...', '', 68974),
(314393, 'esES', 'Por dehgracia, eh el sino de nuehtro pueblo.', '', 68974),
(314392, 'esES', 'Pero ¿dónde ehtaban cuando exhaló su último aliento?', '', 68974),
(314391, 'esES', 'Una vida consagrada a loh loa...', '', 68974),
(314390, 'esES', 'Trágico.', '', 68974),
(314389, 'esES', 'No, no, no, yo no...', '', 68974),
(314388, 'esES', 'No...', '', 68974),
(314387, 'esES', 'Está muerto, Zul\'jan.', '', 68974),
(314386, 'esES', '¡TÍO!', '', 68974),
(314385, 'esES', '¡¿Tío?!', '', 68974),
(314384, 'esES', '<tos>', '', 68974),
(310355, 'esES', 'Yo registraré la Aguja de la Estrella del Alba para buscar la pieza que falta. Ven cuando puedas. Y buena suerte, Rommath.', '', 68974),
(317801, 'esES', '<Tala\'saan reflexiona sobre la pregunta con expresión ausente durante un instante>.\n\nLa capitana Fareeya no nos acompañará en esta misión.\n\nYo seré su representante al frente de los forjados por la Luz destinados a la misión de Maella.\n\nTras perder al alto exarca y a innumerables camaradas, el Ejército de la Luz necesita su liderazgo más que nunca.\n\nPor suerte, no estamos solos, pues Baraat e Y\'mera se han unido a nosotros.\n\nEnaara los ha autorizado tras muchas protestas, pero también ella se quedará atrás, con Sorvos y la capitana.', '', 68974),
(317797, 'esES', '<La expresión de Tala\'saan se tensa>.\n\nMuchos de mis hermanos se perdieron en el vórtice aullante de la Aguja del Vacío.\n\nOtros muchos sufrieron heridas más allá de lo físico.\n\nSé lo que les pasó a muchos en la aguja, $n. Tú también lo viste, ¿verdad? Ira... Confusión... Desesperación.\n\nEsta guerra se ha llevado muchas almas maravillosas. No podía pedirle a Fareeya que diera todavía más.', '', 68974),
(317795, 'esES', 'Soy Tala\'saan, comandante de los velados por la Luz en el Ejército de la Luz.\n\nMe uní a la misión de la hoja de falla Maella a petición suya, para perseguir a las fuerzas del Vacío y a los Hal\'hadar.\n\nNuestra historia con este enemigo es complicada, pero estamos listos para adentrarnos en territorio desconocido.\n\nLos presentes son de la élite al servicio de los velados por la Luz.', '', 68974),
(317656, 'esES', '', 'Tul\'amar aprieta los dientes y se queda callada un momento. Su ojo te mira durante un instante y luego se vuelve a fijar en Tala\'saan.', 68974),
(317572, 'esES', 'Vigilaré de cerca a mi... mejor dicho, a tu nuevo peón.', '', 68974),
(317571, 'esES', 'Nuestro trabajo no ha terminado, pero no me preocupa que Impotus se entrometa. Se quedará en la acrópolis para saborear su victoria.', '', 68974),
(317109, 'esES', 'Esta casucha gélida es endeble. Hay otros mundos que serían mucho más sencillos y aptos.', '', 68974),
(316762, 'esES', 'La hoja de falla Maella nos pidió que acompañáramos a sus tropas en esta expedición.\n\nLos conocimientos de Veraan sobre el Vacío y las operaciones de los Hal\'hadar hacen de ella un activo muy valioso para su misión.\n\n¿Y yo? Bueno, ¡nunca sabes cuándo necesitarás la ayuda de un tecnomántico para desmontar algo!', '', 68974),
(316750, 'esES', '', 'Los archivos de Antorus revelaron que la presencia de la Legión en Val era más bien escasa. Tampoco es que me sorprenda.\n\nGran parte de este mundo está cubierto por enormes tormentas de granizo capaces de perforar los cascos de las naves de la Legión.\n\nAl parecer, perdieron dos naves de invasión en sus intentos por conquistar este mundo.\n\nAcabaron estableciendo algunas fortalezas, pero no eran poco más que puestos avanzados remotos.\n\nPor lo visto, cuando destinaban a alguien a Val solía ser como castigo por sus continuos fracasos.', 68974),
(316562, 'esES', '', '<La archimaga Y\'mera parece concentrada en su tarea. Sus manos se mueven a toda velocidad mientras introduce símbolos rúnicos en la consola>.\n\nLa energía del Vacío del sur proviene de la Acrópolis.\n\nSegún estás lecturas, la fortaleza se adentra en las profundidades, bajo el hielo.', 68974),
(316520, 'esES', '', 'Los Illidari conocen este infierno helado mejor que nadie. La Legión lo llamaba \"Val\" y utilizaba sus gélidas temperaturas para interrogar a los prisioneros.\n\nUn páramo frío y desolador parece el escondite perfecto para un domanaar.\n\n<Maella lanza una mirada nada sutil a Decimus>.', 68974),
(316419, 'esES', '<La baliza tiene dos botones con diferentes destinos: Lunargenta o la Tormenta del Vacío. Resistes la tentación de pulsar ambos botones a la vez>.', '<La baliza tiene dos botones con diferentes destinos: Lunargenta o la Tormenta del Vacío. Resistes la tentación de pulsar ambos botones a la vez>.', 68974),
(316274, 'esES', '', 'Gracias por recuperar estos holoplanos. Ya sabemos de dónde sacan sus artefactos draenei los etéreos.\n\nBajo la isla, hay una cripta que construyó mi pueblo.\n\nLos Hal\'hadar cosechan los guardianes de su interior y los espíritus perturbados de los muertos que yacen ahí.\n\nSus registros indican que hay vigilantes dentro de la tumba, pero, hasta ahora, sus esfuerzos han sido en vano.\n\nCon un poco de suerte, quizás logremos desbaratar sus operaciones.\n\nTala\'saan liderará nuestra incursión en la cripta.', 68974),
(316214, 'esES', '', '<La archimaga Y\'mera abre de par en par los ojos al coger uno de los cristales>.\n\nEstas runas son draénicas, $n. No debería sorprenderme tanto.\n\nLos Hal\'hadar son unos saqueadores de tecnología. Rebuscan en las ruinas de cualquier mundo que visitan.\n\nDeben de haber encontrado la tecnología de cristales de nuestro pueblo en algún planeta, como hicieron con nuestros ensamblajes bélicos.\n\nDeja que examine este, y llévale el resto a Kifaan.Ha estado documentando la tecnología de los Hal\'hadar.\n\nNos vendrá bien la opinión de un tecnomántico del Consorcio.', 68974),
(316212, 'esES', '', '<La archimaga Y\'mera parece concentrada en su tarea. Sus manos se mueven a toda velocidad mientras introduce símbolos rúnicos en la consola>.\n\nCon un poco de suerte y un exhaustivo descifrado, quizá podamos entender qué pretender lograr nuestros enemigos en Naigtal.\n\nNos queda mucho por aprender sobre los Hal\'hadar, adalid.\n\nNo podemos desperdiciar esta oportunidad.', 68974),
(314754, 'esES', 'Tienes a los enemigos detrás, ¡da la vuelta!', 'Tienes a los enemigos detrás, ¡da la vuelta!', 68974),
(313932, 'esES', '', 'La hoja de falla Maella observa con ira la proyección de Decimus.', 68974),
(313749, 'esES', '', '¿Ha llegado el momento? ¿Te envía la hoja de falla Maella? ¡Me vendría bien tu ayuda antes de partir!\n\nHe modificado nuestra tecnología velada por la Luz mediante un sencillo hechizo de ocultación y esa atadura.\n\nCreo que, si combinamos estos dos elementos, podré ocultar a todo nuestro campamento base cuando aterricemos.\n\nPero antes necesito un sujeto de pruebas invisible para poner a prueba los límites de distancia del vínculo.\n\n¿Me ayudarías?', 68974),
(310380, 'esES', 'No tiene las mismas consecuencias eliminar a un imperador domanaar que a un líder mortal.', '', 68974),
(310377, 'esES', '', 'Pertinax ya no será un problema gracias a ti, adalid.', 68974),
(310376, 'esES', 'Y si su \"imperador\" te honra con su presencia, sería todo un detalle que liberaras este páramo de su presencia.', '', 68974),
(310375, 'esES', '', 'Si neutralizamos la presencia del Vacío aquí, la gente que está en casa tendrá un respiro. Siembra el caos, adalid.', 68974),
(310366, 'esES', 'Luz... vileza... Vacío. La receta perfecta para alterar la tensión. Delicioso.', '', 68974),
(309048, 'esES', 'Los Hal\'hadar han incorporado torretas de energía a sus esquifes voladores como \"protección\". Comprobemos lo eficaces que son, ¿te parece?', '', 68974),
(309047, 'esES', 'Sé poca cosa sobre los Hal\'hadar, pero son más competentes que la Guardia de las Sombras. Te sugiero que reduzcas sus efectivos para que no te abrumen más adelante.', '', 68974),
(309020, 'esES', '', 'Nuestros exploradores forjados por la Luz informan de la existencia de una criatura del Vacío antigua que moraba aquí. Recoge muestras para la investigación.', 68974),
(309018, 'esES', 'Tus exploradores con más... \"arrojo\" han intentado usar los volátiles recursos de este mundo. Evita los accidentes desafortunados mientras los recolectas.', '', 68974),
(309015, 'esES', '', 'El sabotaje de la red de portales de los domanaar será un escollo en su invasión de Azeroth. Haz lo que puedas por ralentizarlos.', 68974),
(309014, 'esES', 'No sorprende que otra amenaza ponga en peligro tu misión. Destruye, elimina, triunfa.', '', 68974),
(318546, 'esES', 'El Bancal del Magister siempre ha sido un lugar de aprendizaje.\n\nUn baluarte de conocimiento en el que las ideas se comparten sin discrepancias ni ínfulas.\n\nAun así, por mucho que lo intente, me cuesta observar a los que se fueron y no sentir...\n\n<El magister aprieta los dientes y se queda en silencio>.', 'El Bancal del Magister siempre ha sido un lugar de aprendizaje.\n\nUn baluarte de conocimiento en el que las ideas se comparten sin discrepancias ni ínfulas.\n\nAun así, por mucho que lo intente, me cuesta observar a los que se fueron y no sentir...\n\n<La magistrix aprieta los dientes y se queda en silencio>.', 68974),
(318542, 'esES', '<El elfo noble magister suspira en cuanto te acercas>.\n\nPor favor, no me eches la bronca por estar aquí... Ya no soporto más malas caras o comentarios.\n\nSolo quiero aprender magia y poner en práctica nuevos hechizos. ¿Es pedir demasiado?\n\n¡Todas estas discusiones me están desquiciando!', '<La elfa noble magistrix suspira en cuanto te acercas>.\n\nPor favor, no me eches la bronca por estar aquí... Ya no soporto más malas caras o comentarios.\n\nSolo quiero aprender magia y poner en práctica nuevos hechizos. ¿Es pedir demasiado?\n\n¡Todas estas discusiones me están desquiciando!', 68974),
(317974, 'esES', 'El dominio y la comprensión de la magia siempre ha sido nuestro objetivo. El camino del magister.\n\nEspero que algunos de nuestros hermanos más abiertos de mente puedan ayudar a los demás a darse cuenta de cuáles son nuestros objetivos con el estudio del Vacío.\n\nAdemás, tampoco pretendemos amenazar con el exilio a aquellos que no quieran participar.', 'El dominio y la comprensión de la magia siempre ha sido nuestro objetivo. El camino del magister.\n\nEspero que algunos de nuestros hermanos más abiertos de mente puedan ayudar a los demás a darse cuenta de cuáles son nuestros objetivos con el estudio del Vacío.\n\nAdemás, tampoco pretendemos amenazar con el exilio a aquellos que no quieran participar.', 68974),
(317973, 'esES', 'Según Veldharin, los primeros buscadores de conocimiento investigaron la presencia oscura que percibieron nuestros ancestros en Tirisfal.\n\nNadie sabe a ciencia cierta lo que encontraron, pero, por lo visto, solo unos pocos regresaron con la mente intacta.\n\nLo que sea que vieron o encontraron fue suficiente para que Dath\'Remar prohibiera la magia del Vacío.\n\n¿Crees que Umbric ha podido profundizar en ella? ¿Crees que a nosotros nos lo permitirán?', 'Según Veldharin, los primeros buscadores de conocimiento investigaron la presencia oscura que percibieron nuestros ancestros en Tirisfal.\n\nNadie sabe a ciencia cierta lo que encontraron, pero, por lo visto, solo unos pocos regresaron con la mente intacta.\n\nLo que sea que vieron o encontraron fue suficiente para que Dath\'Remar prohibiera la magia del Vacío.\n\n¿Crees que Umbric ha podido profundizar en ella? ¿Crees que a nosotros nos lo permitirán?', 68974),
(317972, 'esES', '<El magister suspira en cuanto te acercas>.\n\nPor favor, no me eches la bronca por estar aquí... Ya no soporto más malas caras o comentarios.\n\nSolo quiero aprender magia y poner en práctica nuevos hechizos. ¿Es pedir demasiado?\n\nTodas estas discusiones me están desquiciando, y eso es mucho decir... ¡Que he mirado el interior de un agujero negro!', '<La magistrix suspira en cuanto te acercas>.\n\nPor favor, no me eches la bronca por estar aquí... Ya no soporto más malas caras o comentarios.\n\nSolo quiero aprender magia y poner en práctica nuevos hechizos. ¿Es pedir demasiado?\n\nTodas estas discusiones me están desquiciando, y eso es mucho decir... ¡Que he mirado el interior de un agujero negro!', 68974),
(317917, 'esES', 'Si te soy sincero, no tengo claro que esa fuera su intención.\n\nSu traición contra la asamblea y nuestro pueblo fue algo atroz, pero no puedo creer que tuviera la intención de dañar el Omnium.\n\nÉl no querría destruir un repositorio de conocimiento prohibido que le había sido negado durante tanto tiempo.\n\nDe hecho, lo más plausible es que intentara robar el Omnium entero.\n\nQuizá por eso se conformó con una parte.', '', 68974),
(317753, 'esES', '<Veldharin entorna sus ojos vidriosos>.\n\nBuena pregunta, supongo...\n\nEs un nodo de conocimiento estrictamente prohibido. Al menos, eso decretó Dath\'Remar.\n\nAl llegar por primera vez a las costas de Tirisfal, nuestros antepasados se encontraron con una oscuridad que se aferraba a esta tierra.\n\nLos susurros volvían locos a nuestra agotada gente, se alimentaban de su paranoia y azuzaban su miedo y su envidia.\n\nDath\'Remar quiso comprender de dónde venía esa magia, así que envió a los primeros buscadores.\n\nPocos saben lo que encontraron, pero bastó para que él decidiera poner fin a la investigación.\n\nSolo los magistri más fiables y dedicados podrían estudiar el conocimiento de la magícula del Vacío.', '', 68974),
(317750, 'esES', '¡Muy buena pregunta! A ver...\n\nEstá la magícula Arcana, por supuesto. Contiene miles de años de conocimiento de los Altonato que proporcionaron a nuestro pueblo los recursos que necesitaba para prosperar en esta tierra en un momento de necesidad.\n\nTambién tenemos la magícula del Fuego, además de otras magículas elementales, que constituyen los fundamentos de nuestro mundo.\n\nLa magícula de la Luz, a la que los sumos sacerdotes de Lunargenta contribuyeron en gran medida, guarda una curiosa colección de conocimientos sagrados.\n\nY, ya que todo el mundo pregunta, hay magículas prohibidas...\n\nLa del Vacío, la vil, la de nigromancia... Cabe destacar que las restricciones se han suavizado un poco.\n\n<Veldharin frunce el ceño, pensativo>.', '', 68974),
(317749, 'esES', 'Te recomiendo que eches un vistazo a la placa del Omnium. Resume muy bien las intenciones de Dath\'Remar.\n\nEn resumen, sus motivos eran muchos, y tenía grandes ambiciones y un propósito tan claro como el cielo de Canción Eterna.\n\nDath\'Remar vio muchas cosas de joven y no renegó de las fuerzas mágicas de nuestro mundo.', '', 68974),
(317748, 'esES', 'Por supuesto que lo hice, ¡y no solo por el Omnium!\n\nCuando la ciudad cayó, perdí a dos hermanos y a mi querida hermana. Los tres eran magistri...\n\nTraté de ayudar al joven príncipe a reanimarlo... o despertarlo. Estaba muy... frío.\n\nPero, por mucho que lo intentáramos, se negó. No reaccionaba ni a su clave de cifrado.\n\nDespués de que lo sellaran, intenté ayudar a los magistri supervivientes a restaurar el bancal..., pero insistieron en que descansara.\n\nY eso hice, durante unos años. Unos mejores que otros, debo decir... En fin, cuando regresé, el joven Rommath no estaba de humor para intentar detenerme.\n\n¡Dejar la jubilación es justo lo que necesitaba después de todos estos años!', '', 68974),
(317746, 'esES', 'Cuando hablaba de \"preguntas\", me refería a preguntas sobre el Omnium, no sobre mí, pero si insistes...\n\nSoy el custodio Veldharin, nombrado Guardián del Conocimiento por la gran magister... Este... ¿Cómo se llamaba?...\n\nLa gran magister Mo... No, esa no era... En fin, no importa, uno de hace mucho tiempo. Ya he perdido la cuenta.\n\nTras la Segunda Guerra, me animaron a jubilarme. Por lo visto, Anasterian quería que disfrutase de los «muchos días que me quedaban».\n\nEra su forma de decir que ya estaba viejo para este oficio. Así que me fui a vivir con mi hija Elsharin.\n\nEjercía de Buscadora de Conocimiento y embajadora magistral ante el Sagrario del Mago de Ventormenta.', '', 68974),
(317744, 'esES', '¡$gBienvenido:Bienvenida; al Lycaneum!\n\n¡Tienes ante ti un conocimiento y un potencial mágico infinitos!\n\nPor supuesto, te hablo del Omnium del Caminante del Sol. \n\nYo soy su humilde custodio, y mi trabajo consiste en responder y guiar a los jóvenes magistri en su viaje académico por la magia.\n\nSi tienes preguntas, ¡adelante!', '', 68974),
(317738, 'esES', '¿Por qué crees que se llaman \"magículas\"? ¿Por qué no \"manáculos\"? Bueno, eso suena un poco mal...\n\n¿\"Omniculos\"? ¿Y cada cual estudia su omnicu...?\n\nPor Dath\'Remar, creo que no lo estoy arreglando...', '¿Por qué crees que se llaman \"magículas\"? ¿Por qué no \"manáculos\"? Bueno, eso suena un poco mal...\n\n¿\"Omniculos\"? ¿Y cada cual estudia su omnicu...?\n\nPor Dath\'Remar, creo que no lo estoy arreglando...', 68974),
(317730, 'esES', 'No veía semejante caos mágico en el bancal desde... eh... tu altercado con el Magister Umbric.\n\n<El rompehechizos te mira de arriba abajo>.\n\nSerá mejor que te controles esta vez.', 'No veía semejante caos mágico en el bancal desde... eh... tu altercado con el Magister Umbric.\n\n<El rompehechizos te mira de arriba abajo>.\n\nSerá mejor que te controles esta vez.', 68974),
(317724, 'esES', 'Ten cuidado en estos pasillos, $c. \n\nAunque estemos en el Bancal del Magister, hay normas sobre magia muy estrictas.', 'Ten cuidado en estos pasillos, $c. \n\nAunque estemos en el Bancal del Magister, hay normas sobre magia muy estrictas.', 68974),
(317723, 'esES', '<El rompehechizos entorna los ojos y esboza una leve sonrisa>.\n\nNo te preocupes, $n. No pretendo alzar mi guja contra ti.\n\nHe oído que, la última vez que viniste, contabas con la autoridad del señor regente. Mi respuesta no fue nada personal.\n\nMe atengo al juramento de los rompehechizos y esa... desafortunada sucesión de acontecimientos en el bancal debería haberse mantenido entre las cortes y los Magistri, sin involucrarnos.\n\nTe agradezco que no quieras matarme.', '', 68974),
(317722, 'esES', '<Rommath entorna los ojos brevemente>.\n\nConfiamos en que Umbric y sus... seguidores respeten las normas en lo relativo al Omnium.\n\nNo permitiré ningún espectáculo mágico con los horrores del Vacío solo porque los ren\'dorei no se ciñan a las reglas establecidas.\n\nNo obstante, aunque no acabe de fiarme del camino que ha elegido Umbric, estoy dispuesto a confiar en él. Al menos, por ahora.\n\nEl control del Vacío que su gente dice haber conseguido podría abrir debates más fundados sobre la magícula del Vacío.\n\n¡Pero no voy a permitir que la magia del Vacío se convierta en una nueva asignatura en este bancal!', '', 68974),
(317721, 'esES', 'Solo los Magistri pueden estudiar los conocimientos que contiene, y hasta para ellos hay restricciones.\n\nEl propio Dath\'Remar creó esas normas hace generaciones.\n\nEsto garantizó que, mientras descubríamos y catalogábamos la magia nueva y peligrosa, también nos protegíamos a nosotros mismos frente a la naturaleza impredecible de estas fuerzas.\n\nDe hecho, hubo un tiempo en el que el acceso a la magícula vil estaba estrictamente prohibido.\n\nQuién nos iba a decir que las cosas podían cambiar tan rápido...', '', 68974),
(317719, 'esES', '<Umbric sonríe y mira a Rommath>.\n\nCreo que Rommath apenas... tolera mi investigación, pero el Omnium siempre ha tenido medidas de seguridad y normativas para protegerlo.\n\nPor suerte, nunca ha sido un compendio de libre acceso sobre magia.\n\nNo quiero ni pensar en lo que habría hecho Dar\'Khan si hubiera conseguido acceder a él.\n\nLas normas vigentes se remontan a los tiempos de Dath\'Remar.\n\nSus encuentros con el Vacío o la devastación con magia vil que presenció durante la Guerra de los Ancestros son la razón de que se prohibieran esas magias.\n\nDicho lo cual, es un tema que quizá deberíamos debatir.', '', 68974),
(317717, 'esES', 'Una pregunta que todos nos hemos planteado desde que se sumió en el silencio.\n\nNadie sabe exactamente qué pasó. Solo conocemos con certeza el estado en que lo encontramos.\n\nYo no estaba presente cuando cayó el bancal... ni cuando llegó Dar\'Khan..., pero vi las consecuencias.\n\nEl Omnium nunca había estado tan vacío. No quedaba ni rastro de energía. Ni una magícula a la vista.\n\nSolo era un marco árido y silencioso. Resultaba, cuanto menos, inquietante.', '', 68974),
(317715, 'esES', 'Cuando lo encontramos, no vimos nada más que un armazón vacío entre los escombros, sin magículas ni resplandor rúnico.\n\nSalvo por los restos que dejó la matanza de Dar\'Khan, parecía inerte.\n\nLas magículas se crearon como extensiones del Omnium. No pensábamos que pudieran separarse de él.\n\nCuando la reliquia despertó y reaparecieron las magículas, vimos que la matriz central estaba vacía.\n\nEra una anomalía insólita.\n\nLa última magícula a la que se accedió había desaparecido o estaba destruida. O, como en este caso concreto, la habían robado.', '', 68974),
(317714, 'esES', 'Al principio, sí.\n\nSabíamos que había venido al bancal para aniquilar a la asamblea. Había pruebas esparcidas por las paredes y en el propio Omnium.\n\nPero, al registrar su despacho y su casa, solo encontramos pruebas de su obsesión por la magia oscura.\n\nMás tarde, Umbric dijo que la motivación de Drathir eran el poder y el conocimiento, así que dañar el Omnium iría en contra de sus... ambiciones.', '', 68974),
(317713, 'esES', 'No... tengo respuesta para eso.\n\nHicimos todo lo posible para reavivar el Omnium. Ni siquiera la clave de cifrado del Caminante del Sol sirvió.\n\nKael\'thas estaba... afligido.\n\nAl igual que nosotros, había perdido mucho en muy poco tiempo.\n\nBuscaba desesperadamente respuestas para nuestra difícil situación. Para nuestro pueblo.\n\nLos conocimientos del Omnium nos habrían ayudado... Puede que guiaran al príncipe.\n\nPero, al no obtener respuestas, nos vimos impotentes.', '', 68974),
(316792, 'esES', 'Clave de cifrado del Caminante del Sol no reconocida. Marca del eco de reflejo acoplada.', 'Clave de cifrado del Caminante del Sol no reconocida. Marca del eco de reflejo acoplada.', 68974),
(315312, 'esES', 'Estamos en la Aguja de la Estrella del Alba, el lugar donde se crio Dar\'Khan Drathir. En su día fue un lugar tranquilo y agradable.\n\nTras mi exilio de Lunargenta, me puse a buscar las investigaciones de Dar\'Khan sobre el Vacío... y acabé en este lugar.\n\nPor lo visto, llevó gran parte de su investigación en secreto. En lo alto de esta torre es donde abrí la falla a Telogrus por primera vez.\n\nNo sabía que había más secretos por descubrir aquí...', '', 68974),
(314998, 'esES', 'Nunca hemos nombrado buscador a alguien que no perteneciera a los Magistri, pero tú estás... especialmente $gcualificado:cualificada;.\n\nTanto yo como el magister Umbric te encomendaremos tareas de investigación como $gbuscador:buscadora;.\n\nA cambio, por completar dichas tareas, te ofreceremos una serie de poderosos encantamientos rúnicos.\n\nLas runas se encuentran en el folio del Omnium, y tú decides cuál quieres potenciar, por supuesto.\n\n¿Alguna pregunta?', '', 68974),
(314900, 'esES', '<Rommath se queda mirando el silencioso Omnium>.\n\nYa casi hemos terminado. Tenemos la clave de cifrado de Belo\'vir, y Umbric y tú habéis recuperado la magícula del Vacío, así que solo falta una última tarea.\n\nAhora o nunca, $n. ¿Todo listo?', '', 68974),
(314899, 'esES', 'Llevo años estudiando el Omnium. Al igual que los magistrix que me precedieron, he aprendido todo lo que podía ofrecer: runas, hechizos, encantamientos... Todo.\n\nCuando quedó en silencio, fue un día funesto por muchos motivos. Nunca imaginé que volvería a resonar con vida. Es curioso ver hasta dónde hemos llegado.', '', 68974),
(314791, 'esES', 'Por lo visto, Belo\'vir dejó instrucciones para acceder a su cámara..., y llevan mucho tiempo esperándome.\n\nSabiendo cómo era mi predecesor, tengo la certeza de que la complejidad de dichas instrucciones está acorde con su maestría con el hechizo de Reflejo exacto.\n\nEste desafío requiere que nos dividamos las responsabilidades. Yo subiré a mi oficina y me encargaré de los resguardos más complejos.\n\n¿Te importaría ayudar a mis reflejos exactos a desentrañar los tres que están en los niveles exteriores?', '', 68974),
(314746, 'esES', 'Me pregunto cuánto llevaba Dar\'Khan buscando los secretos prohibidos escondidos en la magícula del Vacío.\n\nCuando nos unimos a los Magistri, nos dieron una charla para que supiéramos qué escuelas de magia y cuáles de sus magículas estaban totalmente prohibidas en la asamblea general.\n\nDar\'Khan ya demostraba su afinidad por el Vacío al poco de que llegáramos a Dalaran. Sabía que, como mínimo, le fascinaba.\n\n¿Lo anhelaría desde aquel primer día en que entramos en el Lycaneum?\n\n¿O fue una decisión impulsiva y temeraria que improvisó mientras masacraba a sus hermanos en el bancal?', '', 68974),
(314744, 'esES', 'Tiempo atrás llegué a pensar que ya había visto todos los secretos que Dar\'Khan había escondido en este lugar. Lo que ha ocurrido hoy ha sido... inesperado.\n\nPara extremar las precauciones y porque sé que Rommath me hará preguntas al respecto, voy a asegurarme de que no hay algo más al acecho o escondido por aquí.\n\nRecogeré nuestro ritual y me reuniré contigo en el Bancal del Magister en cuanto hayas ayudado a Rommath a recuperar la clave de cifrado de Belo\'vir.', '', 68974),
(314678, 'esES', 'Mis sospechas estaban bien fundadas... ¿Lo notas en el aire, $n? Un pulso frío y distante..., como un latido débil.\n\nCreo que se trata del componente que estamos buscando, aunque oculto a nuestros ojos.\n\nSi usamos el hechizo y el enfoque adecuados, el Vacío nos revelará los secretos que Dar\'Khan puede haber escondido en este lugar.\n\nMientras tú te dedicas a conectar los anclajes entre sí, yo me pondré a trabajar para terminar este hechizo.\n\nTen cuidado. El Vacío ya intenta atraernos hacia nuestro destino.', '', 68974),
(310354, 'esES', 'Tendremos que deshacer sus salvaguardas. Nos veremos allí.', '', 68974),
(310059, 'esES', 'Ya fuera lo Arcano, lo vil, la Luz o... el Vacío, Dath\'Remar creó el Omnium para conservar el conocimiento en su interior.', '', 68974),
(317919, 'esES', 'Como tantos otros, imagino.\n\nPor lo general, delegaría todas las preguntas en nuestro recién retornado Guardián del Conocimiento, el custodio Veldharin.\n\nNo obstante, dada tu contribución para restaurar el Omnium, satisfaré tu curiosidad.', '', 68974),
(317754, 'esES', 'Ah, sí. La magícula vil. Un nodo de conocimiento prohibido, al menos en su día.\n\nLa magia vil fue una de las primeras que usó Dath\'Remar como catalizador para crear el Omnium.\n\nPudo ver su potencial... y el horror que desataba en los tiempos de los Altonatos. Vio cómo las criaturas del más allá controlaban la magia vil.\n\nEn su momento, contempló el poder destructivo de la magia vil y la Arcana a finales de la Guerra de los Ancestros.\n\nJamás permitiría que una fuerza desconocida tan destructiva volviera a coger desprevenido a su pueblo.\n\nCon el tiempo, compartiría los conocimientos sobre la magia vil y la Legión Ardiente con los Magistri y el Consejo de Tirisfal.\n\nSin embargo, salvo para unos pocos, estaba prohibido estudiar la magícula vil.\n\nAh, cómo cambian los tiempos...', '', 68974),
(317573, 'esES', 'Este planeta..., con todo su potencial..., es mío.', '', 68974),
(309931, 'esES', 'Forestales, ¡preparaos! ¡Mostradles a esos monstruos por qué nos han elegido para proteger el enclave!', 'Forestales, ¡preparaos! ¡Mostradles a esos monstruos por qué nos han elegido para proteger el enclave!', 68974),
(307084, 'esES', 'Ah, $n. \n\nEs agradable ver un rostro menos enfurruñado en esta mesa. Vuelven a tolerarme en mi ciudad, pero ya verás: en cualquier momento, Rommath me lanzará uno de esos misiles de traslación que se le dan tan bien.\n\nResulta que hace tiempo combinó los hechizos Traslación y Misiles Arcanos para darle una lección a cualquiera lo bastante necio como para desafiarlo a un duelo de magos.\n\nNo le gusta admitirlo, pero fui yo quien le enseñó a incorporar un hechizo de invisibilidad a los misiles para no que no los vieran venir.\n\nEn cualquier caso, Lor\'themar me ha dado permiso para estar presente. Me lo estoy pasando muy bien viendo la incomodidad que genera mi persona en los demás.', '', 68974),
(306595, 'esES', 'Tenemos que informar a Lor\'themar de lo que ha ocurrido. Adelántate, adalid.', '', 68974),
(304405, 'esES', 'Los ancianos protectores han sido una fuerza implacable en el campo de batalla en tiempos de guerra y tribulaciones.\n\nEl problema es que hay que esforzarse mucho para que despierten.\n\nOrdenaré a los cuidadores de batalla del anciano Corchoverde que te sigan. El anciano es capaz de lanzar grandes piedras y rocas a nuestros enemigos, así que búscalas.\n\nSe niega a despertar hasta que tenga algo que lanzar.', 'Los ancianos protectores han sido una fuerza implacable en el campo de batalla en tiempos de guerra y tribulaciones.\n\nEl problema es que hay que esforzarse mucho para que despierten.\n\nOrdenaré a los cuidadores de batalla del anciano Corchoverde que te sigan. El anciano es capaz de lanzar grandes piedras y rocas a nuestros enemigos, así que búscalas.\n\nSe niega a despertar hasta que tenga algo que lanzar.', 68974),
(303273, 'esES', '', 'Los ancianos protectores son un elemento de asedio muy útil en las batallas por su capacidad para aniquilar la retaguardia del enemigo.\n\nLa Horda conoce bien su poder para la destrucción.', 68974),
(300503, 'esES', '', 'Eso no debería ser posible. Se lo envié por vía mágica a Ulen, mi senescal a cargo en mi ausencia. Puede que ocurra algo en Suramar.', 68974),
(292933, 'esES', 'Bueno, le dedicaste mucho trabajo, y te lo has ganado.', '', 68974),
(289958, 'esES', '', 'El Pacto de Plata vuelve a Lunargenta una vez más.', 68974);
